DIALOGS = [
[trp_sod_strategy_advisor, "sa_past_story4", [
	], "If it was not for you being in the right place at the right time and recognizing me, I would have died by the hands of my homeland as a Legionnaire Hospitalier hanging disgracefully on a tree.  Your father was a secretive man and the two of you were all that knew about me after the council was disbanded and I agreed to this job.  Call it destiny, coincidence, or divine intervention.  Anyway you look at it, your father's strategy paid off.  It is too bad he is no longer with us.  I have nothing but respect for that man and as his son, I will follow you to the edges of the Earth.", "sa_past_story5", []],
]
